<x-app-layout>
    <div x-data="cvBuilder()" x-init="loadDraft()" :style="'--cv-theme:' + cv.color" class="cv-builder-page min-h-screen bg-slate-100">
        <div class="cv-builder-header border-b border-slate-200 bg-white">
            <div class="mx-auto flex max-w-7xl items-center justify-between px-4 py-5 sm:px-6 lg:px-8">
                <div>
                    <p class="text-sm font-semibold text-indigo-600">CVCraft AI</p>
                    <h1 class="mt-1 text-2xl font-bold tracking-tight text-slate-900">Create your CV</h1>
                </div>
                <div class="flex items-center gap-3">
                    <span class="text-sm text-slate-500" x-text="saved ? 'Draft saved' : 'Unsaved changes'"></span>
                    <button type="button" @click="saveDraft()" class="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-semibold text-slate-700 shadow-sm hover:bg-slate-50">Save draft</button>
                    <button type="button" @click="downloadPdf()" :disabled="downloading" class="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-semibold text-white shadow-sm hover:bg-indigo-500 disabled:cursor-wait disabled:opacity-60" x-text="downloading ? 'Creating PDF...' : 'Download PDF'"></button>
                    <button type="button" @click="resetCv()" class="hidden rounded-lg border border-rose-200 px-4 py-2 text-sm font-semibold text-rose-600 hover:bg-rose-50 sm:inline-flex">Reset</button>
                </div>
            </div>
        </div>

        <div class="mx-auto grid max-w-7xl gap-8 px-4 py-8 sm:px-6 lg:grid-cols-[minmax(0,1fr)_430px] lg:px-8">
            <form @input="saved = false" @submit.prevent="saveDraft" class="cv-editor space-y-6">
                <section class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200">
                    <div class="mb-6 flex items-center justify-between"><div><p class="text-sm font-semibold text-indigo-600">Step 1 of 4</p><h2 class="mt-1 text-lg font-bold text-slate-900">Personal information</h2><p class="mt-1 text-sm text-slate-500">Start with the details recruiters need to reach you.</p></div><span class="rounded-full bg-indigo-50 px-3 py-1 text-xs font-bold text-indigo-700">25% complete</span></div>
                    <div class="grid gap-5 sm:grid-cols-2">
                        <div class="sm:col-span-2"><label for="profile_photo" class="text-sm font-medium text-slate-700">Passport photo <span class="font-normal text-slate-400">(JPG or PNG, optional)</span></label><div class="mt-2 flex items-center gap-4"><div class="flex h-20 w-20 items-center justify-center overflow-hidden rounded-xl border border-dashed border-slate-300 bg-slate-50"><template x-if="cv.photo"><img :src="cv.photo" alt="Profile photo preview" class="h-full w-full object-cover"></template><template x-if="!cv.photo"><span class="text-2xl text-slate-300">+</span></template></div><div><input id="profile_photo" type="file" accept="image/png,image/jpeg" @change="uploadPhoto($event)" class="block w-full text-sm text-slate-500 file:mr-3 file:rounded-lg file:border-0 file:bg-indigo-50 file:px-3 file:py-2 file:text-xs file:font-semibold file:text-indigo-700 hover:file:bg-indigo-100"><p class="mt-1 text-xs text-slate-400">Use a clear, professional headshot.</p></div></div></div>
                        <div class="sm:col-span-2"><label for="full_name" class="text-sm font-medium text-slate-700">Full name</label><input id="full_name" x-model="cv.name" type="text" placeholder="e.g. Alex Morgan" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div>
                        <div><label for="headline" class="text-sm font-medium text-slate-700">Professional title</label><input id="headline" x-model="cv.headline" type="text" placeholder="e.g. Product Designer" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div>
                        <div><label for="location" class="text-sm font-medium text-slate-700">Country name</label><input id="location" x-model="cv.location" type="text" placeholder="e.g. Pakistan" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div>
                        <div><label for="email" class="text-sm font-medium text-slate-700">Email</label><input id="email" x-model="cv.email" type="email" placeholder="you@example.com" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div>
                        <div><label for="phone" class="text-sm font-medium text-slate-700">Phone</label><input id="phone" x-model="cv.phone" type="tel" placeholder="+92 300 0000000" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div>


                    </div>
                </section>


                <section class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><div class="mb-5"><h2 class="text-lg font-bold text-slate-900">Other information</h2><p class="mt-1 text-sm text-slate-500">Add personal details and any extra information for your CV.</p></div><div class="grid gap-5 sm:grid-cols-2"><div><label for="father_name" class="text-sm font-medium text-slate-700">Father name</label><input id="father_name" x-model="cv.fatherName" type="text" placeholder="e.g. Muhammad Ahmed" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div><div><label for="domicile" class="text-sm font-medium text-slate-700">Domicile</label><input id="domicile" x-model="cv.domicile" type="text" placeholder="e.g. Lahore" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div><div><label for="date_of_birth" class="text-sm font-medium text-slate-700">Date of birth</label><input id="date_of_birth" x-model="cv.dateOfBirth" type="date" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div><div><label for="cnic_number" class="text-sm font-medium text-slate-700">CNIC number</label><input id="cnic_number" x-model="cv.cnicNumber" type="text" placeholder="e.g. 35202-1234567-1" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div><div class="sm:col-span-2"><label for="full_address" class="text-sm font-medium text-slate-700">Full address</label><textarea id="full_address" x-model="cv.fullAddress" rows="2" placeholder="House number, street, city, province, country" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></textarea></div><div class="sm:col-span-2"><label for="other_information" class="text-sm font-medium text-slate-700">Additional information <span class="font-normal text-slate-400">(optional)</span></label><textarea id="other_information" x-model="cv.otherInformation" rows="3" placeholder="Add achievements, availability, or any other useful information..." class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></textarea></div></div></section>

                <section class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><div class="mb-5 flex items-start justify-between"><div><h2 class="text-lg font-bold text-slate-900">Work experience</h2><p class="mt-1 text-sm text-slate-500">Add your most recent or relevant role.</p></div><button type="button" class="text-sm font-semibold text-indigo-600 hover:text-indigo-500">+ Add another</button></div><div class="grid gap-5 sm:grid-cols-2"><div><label for="job_title" class="text-sm font-medium text-slate-700">Job title</label><input id="job_title" x-model="cv.jobTitle" type="text" placeholder="e.g. Senior Product Designer" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div><div><label for="company" class="text-sm font-medium text-slate-700">Company</label><input id="company" x-model="cv.company" type="text" placeholder="e.g. Northstar Labs" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div><div><label for="start_date" class="text-sm font-medium text-slate-700">Start date</label><input id="start_date" x-model="cv.startDate" type="text" placeholder="Jan 2021" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div><div><label for="end_date" class="text-sm font-medium text-slate-700">End date</label><input id="end_date" x-model="cv.endDate" type="text" placeholder="Present" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div><div class="sm:col-span-2"><label for="experience" class="text-sm font-medium text-slate-700">What did you accomplish?</label><textarea id="experience" x-model="cv.experience" rows="4" placeholder="Describe your impact, responsibilities, and measurable results..." class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></textarea></div></div></section>

                <section class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><div class="mb-5 flex items-start justify-between"><div><h2 class="text-lg font-bold text-slate-900">Education & skills</h2><p class="mt-1 text-sm text-slate-500">Add one or more degrees, then highlight your strongest skills.</p></div><button type="button" @click="addEducation()" class="rounded-lg bg-indigo-50 px-3 py-2 text-xs font-bold text-indigo-700 hover:bg-indigo-100">+ Add degree</button></div><div class="space-y-5"><template x-for="(education, index) in cv.education" :key="education.id"><div class="rounded-xl border border-slate-200 p-4"><div class="mb-4 flex items-center justify-between"><p class="text-sm font-semibold text-slate-800">Education <span x-text="index + 1"></span></p><button type="button" x-show="cv.education.length > 1" @click="removeEducation(index)" class="text-xs font-semibold text-rose-600 hover:text-rose-500">Remove</button></div><div class="grid gap-4 sm:grid-cols-2"><div><label :for="'degree-' + education.id" class="text-sm font-medium text-slate-700">Degree name</label><input :id="'degree-' + education.id" x-model="education.degree" type="text" placeholder="e.g. BS Computer Science" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div><div><label :for="'board-' + education.id" class="text-sm font-medium text-slate-700">Board / university</label><input :id="'board-' + education.id" x-model="education.institution" type="text" placeholder="e.g. University of Punjab" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div><div><label :for="'total-marks-' + education.id" class="text-sm font-medium text-slate-700">Total marks / credits</label><input :id="'total-marks-' + education.id" x-model="education.totalMarks" type="text" placeholder="e.g. 1100" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div><div><label :for="'obtained-marks-' + education.id" class="text-sm font-medium text-slate-700">Obtained / current marks</label><input :id="'obtained-marks-' + education.id" x-model="education.obtainedMarks" type="text" placeholder="e.g. 920 or 3.6 CGPA" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div><div><label :for="'percentage-' + education.id" class="text-sm font-medium text-slate-700">Percentage / CGPA</label><input :id="'percentage-' + education.id" x-model="education.percentage" type="text" placeholder="e.g. 83.6%" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div></div></div></template><div><label for="skills" class="text-sm font-medium text-slate-700">Skills <span class="font-normal text-slate-400">(separate with commas)</span></label><input id="skills" x-model="cv.skills" type="text" placeholder="Laravel, PHP, JavaScript, Figma, SEO" class="mt-2 block w-full rounded-lg border-slate-300 text-sm shadow-sm focus:border-indigo-500 focus:ring-indigo-500"></div></div></section>



                <section class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><div class="mb-5"><h2 class="text-lg font-bold text-slate-900">Choose a template</h2><p class="mt-1 text-sm text-slate-500">Pick a visual style for your CV preview.</p></div><div class="grid grid-cols-2 gap-3 sm:grid-cols-5"><template x-for="template in templates" :key="template.id"><button type="button" @click="cv.template = template.id; cv.color = template.color" :class="cv.template === template.id ? 'ring-2 ring-indigo-500' : 'ring-1 ring-slate-200'" class="rounded-xl bg-slate-50 p-3 text-left hover:bg-slate-100"><div class="mb-3 h-16 rounded-lg" :style="'background:linear-gradient(135deg,' + template.color + ',#0f172a)'"></div><span class="text-xs font-semibold text-slate-800" x-text="template.name"></span></button></template></div></section>

                <div class="flex items-center justify-between rounded-2xl bg-slate-900 p-5 text-white"><div><p class="font-semibold">Ready to see your CV?</p><p class="mt-1 text-sm text-slate-400">Your preview updates as you type.</p></div><button type="submit" class="rounded-lg bg-indigo-500 px-5 py-2.5 text-sm font-semibold hover:bg-indigo-400">Save CV</button></div>
            </form>

