Â¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â'"></td><td class="border border-slate-300 px-2 py-1.5 text-slate-600" x-text="education.institution || 'Board / University'"></td></tr></template></tbody></table></div></section><section class="mt-5"><h3 class="text-[10px] font-bold uppercase tracking-widest" :style="'color:' + cv.color">Skills</h3><div class="mt-2 flex flex-wrap gap-1.5"><template x-for="skill in cv.skills.split(',').map(skill => skill.trim()).filter(Boolean)" :key="skill"><span class="rounded px-2 py-1 text-[10px]" :style="'background-color:' + cv.color + '18;color:' + cv.color" x-text="skill"></span></template><span x-show="!cv.skills" class="text-xs text-slate-400">Your skills will appear here.</span></div></section></article></aside>
        </div>
    </div>

    <script>
        function cvBuilder() {
            return {
                saved: false,
                colors: ['#4f46e5', '#7c3aed', '#059669', '#e11d48', '#ea580c'],
                templates: [{ id: 'modern', name: 'Modern', color: '#4f46e5' }, { id: 'professional', name: 'Professional', color: '#0f766e' }, { id: 'minimal', name: 'Minimal', color: '#334155' }, { id: 'creative', name: 'Creative', color: '#7c3aed' }, { id: 'ats', name: 'ATS Friendly', color: '#1e293b' }],
                cv: { name: '', headline: '', location: '', email: '', phone: '', photo: '', color: '#4f46e5', template: 'modern', summary: '', jobTitle: '', company: '', startDate: '', endDate: '', experience: '', otherInformation: '', fatherName: '', domicile: '', dateOfBirth: '', cnicNumber: '', fullAddress: '', skills: '', languages: '', interests: '', education: [{ id: Date.now(), degree: '', institution: '', totalMarks: '', obtainedMarks: '', percentage: '' }], projects: [], certifications: [] },
                loadDraft() {
                    const draft = localStorage.getItem('cvcraft-draft');
                    if (draft) this.cv = { ...this.cv, ...JSON.parse(draft) };
                    if (!Array.isArray(this.cv.education) || this.cv.education.length === 0) this.cv.education = [{ id: Date.now(), degree: '', institution: '', totalMarks: '', obtainedMarks: '', percentage: '' }];
                    if (!Array.isArray(this.cv.projects)) this.cv.projects = [];
                    if (!Array.isArray(this.cv.certifications)) this.cv.certifications = [];
                },
                downloading: false,
                downloadPdf() {
                    this.downloading = true;
                    fetch('{{ route('cv-builder.pdf') }}', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Accept': 'application/pdf',
                            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content,
                        },
                        body: JSON.stringify(this.cv),
                    }).then((response) => {
                        if (!response.ok) throw new Error('PDF could not be created.');
                        return response.blob();
                    }).then((blob) => {
                        const url = URL.createObjectURL(blob);
                        const link = document.createElement('a');
                        link.href = url;
                        link.download = 'cvcraft-cv.pdf';
                        document.body.appendChild(link);
                        link.click();
                        link.remove();
                        URL.revokeObjectURL(url);
                    }).catch(() => {
                        alert('PDF could not be created. Please try again.');
                    }).finally(() => { this.downloading = false; });
                },
                saveDraft() {
                    localStorage.setItem('cvcraft-draft', JSON.stringify(this.cv));
                    this.saved = true;
                },
                addEducation() {
                    this.cv.education.push({ id: Date.now() + Math.random(), degree: '', institution: '', totalMarks: '', obtainedMarks: '', percentage: '' });
                },
                removeEducation(index) {
                    this.cv.education.splice(index, 1);
                },
                addProject() {
                    this.cv.projects.push({ id: Date.now() + Math.random(), name: '', url: '', description: '' });
                },
                addCertification() {
                    this.cv.certifications.push({ id: Date.now() + Math.random(), name: '', organization: '' });
                },
                removeItem(collection, index) {
                    this.cv[collection].splice(index, 1);
                },
                resetCv() {
                    if (!confirm('Are you sure you want to clear your CV?')) return;
                    localStorage.removeItem('cvcraft-draft');
                    window.location.reload();
                },
                uploadPhoto(event) {
                    const file = event.target.files[0];
                    if (!file) return;
                    if (file.size > 2 * 1024 * 1024) {
                        alert('Please select an image smaller than 2 MB.');
                        event.target.value = '';
                        return;
                    }
                    const reader = new FileReader();
                    reader.onload = (loadEvent) => { this.cv.photo = loadEvent.target.result; this.saved = false; };
                    reader.readAsDataURL(file);
                },
            };
        }
    </script>
</x-app-layout>







































